namespace ghidra.util.table.field;

using ghidra.docking.settings;
using ghidra.framework.plugintool;
using ghidra.program.model.address;
using ghidra.program.model.listing;
using ghidra.program.model.listing;
using ghidra.program.util;

/**
 * This table column displays the Label for either the program location or the address
 * associated with a row in the table.
 */
public class EOLCommentTableColumn : ProgramLocationTableColumnExtensionPoint<ProgramLocation, string> {

	/* @Override */
	public ProgramLocation getProgramLocation(ProgramLocation rowObject, Settings settings,
			Program program, ServiceProvider serviceProvider) {

		string comment = getEOLComment(rowObject, program);
		if (comment != null) {
			return new EolCommentFieldLocation(program, rowObject.getAddress(), null, null, 0, 0,
				0);
		}
		return rowObject;
	}

	/* @Override */
	public string getColumnName() {
		return "EOL Comment";
	}

	/* @Override */
	public string getValue(ProgramLocation rowObject, Settings settings, Program program,
			ServiceProvider serviceProvider)
    {
		return getEOLComment(rowObject, program);
	}

	private string getEOLComment(ProgramLocation loc, Program program)
    {
		ProgramLocation location = loc;
		if (loc is VariableLocation) {
			return null;
		}
		Address address = location.getAddress();
		return program.getListing().getComment(CommentType.EOL, address);
	}
}
